.macro _ldrel reg sym
#ifdef __APPLE__
adrp \reg, \sym@PAGE
add  \reg, \reg, \sym@PAGEOFF
#else
adrp \reg, \sym
add  \reg, \reg, :lo12:\sym
#endif
.endm

cdecl(cml_main):
     _ldrel x0, cake_main            /* arg1: entry address */
     _ldrel x1, cdecl(cml_heap)      /* arg2: first address of heap */
     ldr    x1,[x1]
     _ldrel x2, cake_bitmaps
     str    x2,[x1]                  /* store bitmap pointer */
     _ldrel x2, cdecl(cake_bitmaps_buffer_begin)
     str    x2,[x1,#8]               /* bitmap buffer start */
     _ldrel x2, cdecl(cake_bitmaps_buffer_end)
     str    x2,[x1,#16]              /* bitmap buffer end */
     _ldrel x2, cdecl(cake_codebuffer_begin)
     str    x2,[x1,#24]              /* code buffer start */
     _ldrel x2, cdecl(cake_codebuffer_end)
     str    x2,[x1,#32]              /* code buffer end */
     _ldrel x2, cdecl(cml_stack)     /* arg3: first address of stack */
     ldr    x2,[x2]
     _ldrel x3, cdecl(cml_stackend)  /* arg4: first address past the stack */
     ldr    x3,[x3]
     b      cake_main
     .ltorg

/* CakeML FFI interface (each block is 16 bytes long) */

